<?php
require_once __DIR__.'/../includes/session.php';require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../config/database.php';
if($_SERVER['REQUEST_METHOD']!=='POST'||!isset($_SESSION['participant_id'],$_SESSION['campaign_id']))redirect('../index.php');if(!verify_csrf_token($_POST['csrf_token']??''))redirect('form.php?error='.urlencode('Security token expired. Please try again.'));
$participantId=(int)$_SESSION['participant_id'];$campaignId=(int)$_SESSION['campaign_id'];$answers=is_array($_POST['answers']??null)?$_POST['answers']:[];$questionsResult=pg_query_params($conn,'SELECT * FROM feedback_questions WHERE campaign_id=$1 ORDER BY display_order,id',[$campaignId]);if(!$questionsResult||pg_num_rows($questionsResult)===0)redirect('form.php?error='.urlencode('This campaign has no questions.'));
$validated=[];$errors=[];while($q=pg_fetch_assoc($questionsResult)){$id=(int)$q['id'];$value=$answers[$id]??null;$missing=$value===null||$value===''||(is_array($value)&&count(array_filter($value,fn($x)=>trim((string)$x)!==''))===0);if($q['is_required']==='t'&&$missing){$errors[]='Please answer: '.$q['prompt'];continue;}if($missing){$validated[$id]=['type'=>$q['question_type'],'value'=>null];continue;}$type=$q['question_type'];if($type==='rating'){$rating=filter_var($value,FILTER_VALIDATE_INT);if($rating===false||$rating<1||$rating>5)$errors[]='Invalid rating for: '.$q['prompt'];else$validated[$id]=['type'=>$type,'value'=>$rating];}elseif($type==='text'){$text=trim((string)$value);if(mb_strlen($text)>5000)$errors[]='A written answer is too long.';else$validated[$id]=['type'=>$type,'value'=>$text];}else{$allowed=json_decode($q['options'],true)?:[];$selected=array_values(array_unique(array_map('strval',(array)$value)));if($type==='single_choice'&&count($selected)!==1)$errors[]='Choose one option for: '.$q['prompt'];elseif(array_diff($selected,$allowed))$errors[]='Invalid selection for: '.$q['prompt'];else$validated[$id]=['type'=>$type,'value'=>$selected];}}
if($errors)redirect('form.php?error='.urlencode($errors[0]));if(!pg_query($conn,'BEGIN'))redirect('form.php?error='.urlencode('Unable to start submission.'));
try{$p=pg_query_params($conn,'SELECT status,campaign_id FROM feedback_participants WHERE id=$1 FOR UPDATE',[$participantId]);if(!$p||pg_num_rows($p)!==1||pg_fetch_result($p,0,'status')!=='active'||(int)pg_fetch_result($p,0,'campaign_id')!==$campaignId)throw new Exception('This account has already responded or is unavailable.');$c=pg_query_params($conn,"SELECT status,start_at,end_at,(status='active' AND (start_at IS NULL OR start_at<=CURRENT_TIMESTAMP) AND (end_at IS NULL OR end_at>=CURRENT_TIMESTAMP)) AS accepting FROM feedback_campaigns WHERE id=$1 FOR SHARE",[$campaignId]);if(!$c||pg_num_rows($c)!==1)throw new Exception('Campaign unavailable.');$campaign=pg_fetch_assoc($c);if($campaign['accepting']!=='t')throw new Exception($campaign['status']!=='active'?'This campaign is not active.':'This campaign is outside its scheduled response period.');$reference='FB-'.strtoupper(bin2hex(random_bytes(5)));$ipHash=hash('sha256',($_SERVER['REMOTE_ADDR']??'').'|'.$campaignId);$s=pg_query_params($conn,'INSERT INTO feedback_submissions(campaign_id,participant_id,reference_code,ip_hash) VALUES($1,$2,$3,$4) RETURNING id',[$campaignId,$participantId,$reference,$ipHash]);if(!$s)throw new Exception('Unable to create submission.');$submissionId=(int)pg_fetch_result($s,0,0);foreach($validated as $questionId=>$answer){if($answer['value']===null)continue;$rating=$answer['type']==='rating'?$answer['value']:null;$text=$answer['type']==='text'?$answer['value']:null;$options=in_array($answer['type'],['single_choice','multiple_choice'],true)?json_encode($answer['value']):'[]';if(!pg_query_params($conn,'INSERT INTO feedback_answers(submission_id,question_id,rating_value,text_value,selected_options) VALUES($1,$2,$3,$4,$5::jsonb)',[$submissionId,$questionId,$rating,$text,$options]))throw new Exception('Unable to save an answer.');}if(!pg_query_params($conn,"UPDATE feedback_participants SET status='responded',responded_at=NOW() WHERE id=$1",[$participantId]))throw new Exception('Unable to finalize participant status.');if(!pg_query($conn,'COMMIT'))throw new Exception('Unable to commit submission.');$_SESSION['feedback_reference']=$reference;unset($_SESSION['participant_id'],$_SESSION['participant_name'],$_SESSION['campaign_id'],$_SESSION['campaign_title']);redirect('thank_you.php');}catch(Throwable $e){pg_query($conn,'ROLLBACK');error_log('Feedback submission failed: '.$e->getMessage());redirect('form.php?error='.urlencode($e->getMessage()));}
